@Component("careTask-handler")
@ProcessingGroup("careTask-processing-group")
public class CareTaskEventHandler {
	
	// core constructor
	CareTaskEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCareTaskEvent
     */
    @EventHandler
    public void handle( CreateCareTaskEvent event) {
        entityManager.persist(new CareTask(event.getCareTaskId(), event.getDescription(), event.getDueDate(), event.getCarePlan(), event.getAssignedTo(), event.getEncounter(), event.getStatus(), event.getPriority()));
    }

    /*
     * @param	event UpdateCareTaskEvent
     */
    @EventHandler
    public CareTask handle( UpdateCareTaskEvent event) {
    	entityManager.merge(new CareTask(event.getCareTaskId(), event.getDescription(), event.getDueDate(), event.getCarePlan(), event.getAssignedTo(), event.getEncounter(), event.getStatus(), event.getPriority()));
    }
    
    /*
     * @param	event DeleteCareTaskEvent
     */
    @EventHandler
    public void on( DeleteCareTaskEvent event) {
    	CareTask entity = new CareTask();
   
    	// ------------------------------------------
    	// apply the CareTaskId
    	// ------------------------------------------
    	entity.setCareTaskId( event.getCareTaskId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CareTaskRepository careTaskEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CareTaskEventHandler.class.getName());

}
